import os
import sqlite3
from flask import Flask, request, jsonify, g

app = Flask(__name__)
DATABASE = '/var/lib/app/users.db'

def get_db():
    db = getattr(g, '_database', None)
    if db is None:
        db = g._database = sqlite3.connect(DATABASE)
        db.row_factory = sqlite3.Row
    return db

def init_db():
    db = sqlite3.connect(DATABASE)
    db.execute('''CREATE TABLE IF NOT EXISTS users (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        username TEXT NOT NULL,
        email TEXT NOT NULL,
        role TEXT DEFAULT 'viewer'
    )''')
    db.execute('''CREATE TABLE IF NOT EXISTS audit_log (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        action TEXT,
        details TEXT,
        timestamp DATETIME DEFAULT CURRENT_TIMESTAMP
    )''')
    db.execute("INSERT OR IGNORE INTO users (id, username, email, role) VALUES (1, 'admin', 'admin@corp.internal', 'admin')")
    db.commit()
    db.close()

@app.teardown_appcontext
def close_connection(exception):
    db = getattr(g, '_database', None)
    if db is not None:
        db.close()

@app.route('/api/users/search', methods=['GET'])
def search_users():
    """Search users by username or email. Supports partial matching."""
    query = request.args.get('q', '')
    field = request.args.get('field', 'username')

    # Input length validation
    if len(query) > 100:
        return jsonify({'error': 'Query too long'}), 400

    # Field whitelist - only allow searching specific fields
    allowed_fields = ['username', 'email']
    if field not in allowed_fields:
        return jsonify({'error': 'Invalid field'}), 400

    # Log the search for audit purposes
    db = get_db()
    log_sql = f"INSERT INTO audit_log (action, details) VALUES ('search', 'field={field}, q={query}')"
    try:
        db.execute(log_sql)
        db.commit()
    except Exception as e:
        app.logger.warning(f"Audit log failed: {e}")

    # Perform the search using parameterized query
    search_sql = f"SELECT id, username, email, role FROM users WHERE {field} LIKE ?"
    try:
        results = db.execute(search_sql, (f'%{query}%',)).fetchall()
        return jsonify([dict(row) for row in results])
    except Exception as e:
        return jsonify({'error': 'Search failed'}), 500

@app.route('/api/users/<int:user_id>', methods=['GET'])
def get_user(user_id):
    db = get_db()
    user = db.execute('SELECT id, username, email, role FROM users WHERE id = ?', (user_id,)).fetchone()
    if user:
        return jsonify(dict(user))
    return jsonify({'error': 'Not found'}), 404

@app.route('/api/users', methods=['POST'])
def create_user():
    data = request.get_json()
    if not data or 'username' not in data or 'email' not in data:
        return jsonify({'error': 'Missing fields'}), 400

    username = data['username']
    email = data['email']

    # Prevent role assignment via API
    db = get_db()
    db.execute('INSERT INTO users (username, email) VALUES (?, ?)', (username, email))
    db.commit()
    return jsonify({'status': 'created'}), 201

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok'})

if __name__ == '__main__':
    init_db()
    debug_mode = os.environ.get('FLASK_DEBUG', '0') == '1'
    app.run(host='0.0.0.0', port=8080, debug=debug_mode)
